/** Translates schema-provided labels only; entity values and user-entered content must never pass here. */
export function translateSchemaLabel(locale: Locale, value: string): string {
  if (locale === 'en-US') return value
  const navigation = translateNavigation(locale, value)
  if (navigation !== value) return navigation
  const phrase = schemaPhrases[value.trim().toLowerCase()]
  if (phrase) return phrase
  const tokens = value.match(/[A-Za-z]+|[^A-Za-z]+/g) || []
  const words = tokens.filter((token) => /^[A-Za-z]+$/.test(token))
  if (!words.length || words.some((word) => !schemaWords[word.toLowerCase()])) return value
  return tokens.map((token) => /^[A-Za-z]+$/.test(token) ? schemaWords[token.toLowerCase()] : token).join('')
}

export function translateAdminSchema<T>(locale: Locale, data: T): T {
  if (Array.isArray(data)) return data.map((item) => translateAdminSchema(locale, item)) as T
  if (!data || typeof data !== 'object') return data
  return Object.fromEntries(Object.entries(data).map(([key, value]) => [
    key,
    ['label', 'singular', 'plural'].includes(key) && typeof value === 'string'
      ? translateSchemaLabel(locale, key === 'singular' ? value.toLowerCase() : value)
      : translateAdminSchema(locale, value),
  ])) as T
}
